import os,sys,select,struct,fcntl,termios,subprocess,time

def run(args, data=b'', env=None, size=(24,80,800,480), stdin_tty=False, stdout_tty=True, respond=None, timeout=1):
    master, slave=os.openpty()
    fcntl.ioctl(slave,termios.TIOCSWINSZ,struct.pack('HHHH',*size))
    # Leave normal canonical/output modes in place, as with a real terminal.
    p=subprocess.Popen(['/workspace/executable']+args,stdin=slave if stdin_tty else subprocess.PIPE,stdout=slave if stdout_tty else subprocess.PIPE,stderr=subprocess.PIPE,env={**os.environ,**(env or {})},close_fds=True)
    os.close(slave)
    if not stdin_tty:
        p.stdin.write(data); p.stdin.close()
    elif data:
        os.write(master,data)
    outputs={'tty':b'','stdout':b'','stderr':b''}
    fds={master:'tty',p.stderr.fileno():'stderr'}
    if not stdout_tty: fds[p.stdout.fileno()]='stdout'
    t=time.time(); sent=False
    while fds and time.time()-t < timeout:
        rs,_,_=select.select(list(fds),[],[],.02)
        for fd in rs:
            try: buf=os.read(fd,65536)
            except OSError: buf=b''
            if not buf: fds.pop(fd,None); continue
            outputs[fds[fd]]+=buf
            if respond and not sent and b'\x1b[c' in outputs['tty']:
                os.write(master,respond); sent=True
        if p.poll() is not None and not rs: break
    timedout=p.poll() is None
    if timedout: p.kill()
    p.wait()
    try: os.close(master)
    except: pass
    return p.returncode,outputs,timedout,round(time.time()-t,3)

if __name__=='__main__':
    cases=[([],b'',{},(24,80,800,480),False),(['foo'],b'{"foo":1}\n',{},(24,80,800,480),False),(['foo'],b'{"foo":1}\n',{'TERM_PROGRAM':'iTerm.app'},(24,80,800,480),False),(['foo'],b'',{'TERM_PROGRAM':'iTerm.app'},(24,80,800,480),False),(['foo'],b'{"foo":1}\n',{'TERM_PROGRAM':'iTerm.app'},(24,80,0,0),False),(['foo'],b'{"foo":1}\n{"foo":2}\n',{'TERM_PROGRAM':'iTerm.app'},(24,80,800,480),False),(['-rows','3','foo'],b'{"foo":1}\n',{'TERM_PROGRAM':'iTerm.app'},(24,80,800,480),False),(['foo'],b'{}\n',{'TERM_PROGRAM':'iTerm.app'},(24,80,800,480),False),(['foo'],b'',{'TERM_PROGRAM':'iTerm.app'},(24,80,800,480),True)]
    for n,(args,data,env,size,stdin_tty) in enumerate(cases):
        print('\nCASE',n,args,repr(data),env,size,'stdin_tty',stdin_tty)
        rc,outs,tm,elapsed=run(args,data,env,size,stdin_tty=stdin_tty)
        print('return',rc,'timeout',tm,'elapsed',elapsed)
