import os,select,struct,fcntl,termios,subprocess,time

def run(args, data=b'', env=None, size=(24,80,800,480), replies=None, timeout=1, ttyin=False):
 m,s=os.openpty(); fcntl.ioctl(s,termios.TIOCSWINSZ,struct.pack('HHHH',*size))
 p=subprocess.Popen(['/workspace/executable']+args,stdin=s if ttyin else subprocess.PIPE,stdout=s,stderr=subprocess.PIPE,env={**os.environ,**(env or {})})
 os.close(s)
 if not ttyin: p.stdin.write(data);p.stdin.close()
 fds={m:'out',p.stderr.fileno():'err'};outs={'out':b'','err':b''};events=[];sent=[];t=time.monotonic()
