  rs,_,_=select.select(list(fds),[],[],.02)
  for fd in rs:
   try: b=os.read(fd,65536)
   except OSError: b=b''
   if not b: fds.pop(fd);continue
   outs[fds[fd]]+=b
   events.append((round(time.monotonic()-t,3),fds[fd],b))
  for index,(trigger,reply) in enumerate(replies or []):
   if index not in sent and trigger in outs['out']:
