package main

import (
	"fmt"
	"strconv"
	"strings"
)

// A field is one series in a graph. A graph argument can contain any number
// of fields, joined with a plus sign.
type field struct {
	path    string
	counter bool
	marker  bool
}

type graphSpec []field

func parseSpecs(args []string) ([]graphSpec, error) {
	graphs := make([]graphSpec, 0, len(args))
	for _, arg := range args {
		graph := make(graphSpec, 0)
		for _, part := range strings.Split(arg, "+") {
			f := field{path: part}
			if i := strings.IndexByte(part, ':'); i >= 0 {
				f.path = part[i+1:]
				for _, option := range strings.Split(part[:i], ",") {
					switch option {
					case "counter":
						f.counter = true
					case "marker":
						f.marker = true
					default:
						return nil, fmt.Errorf("invalid field option: %s", option)
					}
				}
			}
			graph = append(graph, f)
		}
		graphs = append(graphs, graph)
	}
	return graphs, nil
}

// query follows the dotted object/array notation accepted by field specs.
// Bracketed array selectors occupy a whole component (for example a.[0].b).
func query(value any, path string) (any, error) {
	if path == "." {
		return value, nil
	}
	parts := strings.Split(path, ".")
	for i, part := range parts {
		if part == "" && i < len(parts)-1 {
			part = "."
		}
		if len(part) > 2 && part[0] == '[' && part[len(part)-1] == ']' {
			index, err := strconv.Atoi(part[1 : len(part)-1])
			if err != nil {
				return nil, err
			}
			array, ok := value.([]any)
			if !ok {
				return nil, fmt.Errorf("%s is not an array. []", part)
			}
			if index >= len(array) {
				return nil, fmt.Errorf("%s index out of range.", part)
			}
			value = array[index]
		} else {
			object, ok := value.(map[string]any)
			if !ok {
				return nil, fmt.Errorf("%s is not an object. map[]", part)
			}
			value, ok = object[part]
			if !ok {
				return nil, fmt.Errorf("%s does not exist.", part)
			}
		}
	}
	return value, nil
}
EOF
