package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"sync"
	"time"
)

type sourceItem struct {
	value any
	err   error
}

func decodeItem(raw []byte) sourceItem {
	var value any
	err := json.Unmarshal(raw, &value)
	return sourceItem{value, err}
}

func readLines(input io.Reader) <-chan sourceItem {
	items := make(chan sourceItem)
	go func() {
		defer close(items)
		scanner := bufio.NewScanner(input)
		for scanner.Scan() {
			item := decodeItem(scanner.Bytes())
			items <- item
			if item.err != nil {
				return
			}
		}
		if err := scanner.Err(); err != nil {
			items <- sourceItem{err: err}
		}
	}()
	return items
}

func pollHTTP(url string, interval time.Duration, stop <-chan struct{}) <-chan sourceItem {
	items := make(chan sourceItem)
	go func() {
		defer close(items)
		ticker := time.NewTicker(interval)
		defer ticker.Stop()
		for {
			resp, err := http.Get(url)
			var item sourceItem
			if err != nil {
				item.err = err
			} else {
				raw, readErr := io.ReadAll(resp.Body)
				resp.Body.Close()
				if readErr != nil {
					item.err = readErr
				} else {
					item = decodeItem(raw)
				}
			}
			select {
			case items <- item:
			case <-stop:
				return
			}
			if item.err != nil {
				return
			}
			select {
			case <-ticker.C:
			case <-stop:
				return
			}
		}
	}()
	return items
}

type series struct {
	field
	values []float64
	last   float64
}

// pointStore keeps a rolling, fixed-width history for each configured series.
type pointStore struct {
	mu       sync.Mutex
	graphs   [][]series
	steps    int
	interval time.Duration
}

func newPointStore(specs []graphSpec, steps int, interval time.Duration) *pointStore {
	p := &pointStore{steps: steps, interval: interval}
	for _, g := range specs {
		s := make([]series, 0, len(g))
		for _, f := range g {
			s = append(s, series{field: f})
		}
		p.graphs = append(p.graphs, s)
	}
	return p
}

func (p *pointStore) add(object any) error {
	p.mu.Lock()
	defer p.mu.Unlock()
	for i := range p.graphs {
		for j := range p.graphs[i] {
			s := &p.graphs[i][j]
			value, err := query(object, s.path)
			if err != nil {
				return fmt.Errorf("cannot get %s: %s", s.path, err)
			}
			v, ok := value.(float64)
			if !ok {
				return fmt.Errorf("invalid type %s: %T", s.path, value)
			}
			if s.counter {
				previous := s.last
				s.last = v
				v -= previous
				if v < 0 {
					v = 0
				}
				v /= p.interval.Seconds()
			}
			if p.steps <= 0 {
				// Invalid history sizes fail when the first value is inserted,
				// rather than during command-line parsing.
				s.values = make([]float64, p.steps)
				s.values[p.steps-1] = v
			}
			s.values = append(s.values, v)
			if len(s.values) > p.steps {
				copy(s.values, s.values[len(s.values)-p.steps:])
				s.values = s.values[:p.steps]
			}
		}
	}
	return nil
}

func (p *pointStore) snapshot() [][]series {
	p.mu.Lock()
	defer p.mu.Unlock()
	out := make([][]series, len(p.graphs))
	for i, g := range p.graphs {
		out[i] = make([]series, len(g))
		for j, s := range g {
			out[i][j] = s
			out[i][j].values = make([]float64, p.steps)
			count := len(s.values)
			if count > p.steps {
				count = p.steps
			}
			copy(out[i][j].values[p.steps-count:], s.values[len(s.values)-count:])
		}
	}
	return out
}
EOF"}

