package main

import (
	"errors"
	"fmt"
	"math"
	"os"
	"strings"
	"syscall"
	"unsafe"
)

type windowSize struct {
	rows, columns, pixelWidth, pixelHeight uint16
}

func ioctl(fd uintptr, request uintptr, value unsafe.Pointer) error {
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, request, uintptr(value))
	if err != 0 {
		return err
	}
	return nil
}

func terminalSize(f *os.File) (windowSize, error) {
	var size windowSize
	err := ioctl(f.Fd(), syscall.TIOCGWINSZ, unsafe.Pointer(&size))
	return size, err
}

func isTerminal(f *os.File) bool {
	var state syscall.Termios
	return ioctl(f.Fd(), syscall.TCGETS, unsafe.Pointer(&state)) == nil
}

func rawTerminal(f *os.File) (func(), error) {
	var old syscall.Termios
	if err := ioctl(f.Fd(), syscall.TCGETS, unsafe.Pointer(&old)); err != nil {
		return nil, err
	}
	state := old
	state.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP |
		syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	state.Oflag &^= syscall.OPOST
