package main

import (
	"fmt"
	"image"
	"image/color"
	"math"
	"strconv"
	"strings"
	"time"
)

var seriesColors = []color.NRGBA{
	{0, 116, 217, 255}, {255, 133, 27, 255}, {255, 65, 54, 255},
	{46, 204, 64, 255}, {177, 13, 201, 255}, {255, 220, 0, 255},
	{127, 219, 255, 255}, {240, 18, 190, 255}, {61, 153, 112, 255},
	{57, 204, 204, 255}, {1, 255, 112, 255}, {133, 20, 75, 255},
}

// canvas is a small antialiased raster drawing surface. Coordinates are in
// pixels, and all compositing uses premultiplied alpha as required by RGBA.
type canvas struct{ image *image.RGBA }

type vector struct{ x, y float64 }

func (c canvas) blend(x, y int, paint color.NRGBA, coverage float64) {
	if !image.Pt(x, y).In(c.image.Bounds()) || coverage <= 0 {
		return
	}
	if coverage > 1 {
		coverage = 1
	}
	a := uint32(math.Round(float64(paint.A) * coverage))
	if a == 0 {
		return
	}
	off := c.image.PixOffset(x, y)
	pixel := c.image.Pix[off : off+4]
	inv := 255 - a
	pixel[0] = uint8((uint32(paint.R)*a + uint32(pixel[0])*inv) / 255)
	pixel[1] = uint8((uint32(paint.G)*a + uint32(pixel[1])*inv) / 255)
	pixel[2] = uint8((uint32(paint.B)*a + uint32(pixel[2])*inv) / 255)
	pixel[3] = uint8(a + uint32(pixel[3])*inv/255)
}

func (c canvas) box(x0, y0, x1, y1 float64, paint color.NRGBA) {
	if x0 > x1 {
		x0, x1 = x1, x0
	}
	if y0 > y1 {
		y0, y1 = y1, y0
	}
	bounds := c.image.Bounds()
	for y := maxInt(int(math.Floor(y0)), bounds.Min.Y); y < minInt(int(math.Ceil(y1)), bounds.Max.Y); y++ {
		cy := math.Min(float64(y+1), y1) - math.Max(float64(y), y0)
		for x := maxInt(int(math.Floor(x0)), bounds.Min.X); x < minInt(int(math.Ceil(x1)), bounds.Max.X); x++ {
			cx := math.Min(float64(x+1), x1) - math.Max(float64(x), x0)
			c.blend(x, y, paint, cx*cy)
		}
	}
}

func (c canvas) line(x0, y0, x1, y1, width float64, paint color.NRGBA) {
	if math.IsNaN(x0+y0+x1+y1) || math.IsInf(x0+y0+x1+y1, 0) {
		return
	}
	if x0 == x1 {
		c.box(x0-width/2, y0, x1+width/2, y1, paint)
		return
	}
	if y0 == y1 {
		c.box(x0, y0-width/2, x1, y1+width/2, paint)
		return
	}
	dx, dy := x1-x0, y1-y0
	distance := math.Hypot(dx, dy)
	nx, ny := -dy/distance*width/2, dx/distance*width/2
	c.polygon([]vector{{x0 + nx, y0 + ny}, {x1 + nx, y1 + ny}, {x1 - nx, y1 - ny}, {x0 - nx, y0 - ny}}, paint)
}

func (c canvas) polygon(points []vector, paint color.NRGBA) {
	if len(points) < 3 {
		return
	}
	loX, loY, hiX, hiY := points[0].x, points[0].y, points[0].x, points[0].y
	for _, p := range points {
		loX, loY = math.Min(loX, p.x), math.Min(loY, p.y)
		hiX, hiY = math.Max(hiX, p.x), math.Max(hiY, p.y)
	}
	if math.IsNaN(loX+loY+hiX+hiY) || math.IsInf(loX+loY+hiX+hiY, 0) {
		return
	}
	bounds := c.image.Bounds()
	for y := maxInt(int(math.Floor(loY)), bounds.Min.Y); y < minInt(int(math.Ceil(hiY)), bounds.Max.Y); y++ {
		for x := maxInt(int(math.Floor(loX)), bounds.Min.X); x < minInt(int(math.Ceil(hiX)), bounds.Max.X); x++ {
			// A 4x4 coverage grid smooths diagonal graph edges while keeping
			// the renderer independent of external graphics libraries.
			inside := 0
			for sy := 0; sy < 4; sy++ {
				py := float64(y) + (float64(sy)+.5)/4
				for sx := 0; sx < 4; sx++ {
					px := float64(x) + (float64(sx)+.5)/4
					winding := false
					last := points[len(points)-1]
					for _, p := range points {
						if (p.y > py) != (last.y > py) && px < (last.x-p.x)*(py-p.y)/(last.y-p.y)+p.x {
							winding = !winding
						}
						last = p
					}
					if winding {
						inside++
					}
				}
			}
			c.blend(x, y, paint, float64(inside)/16)
		}
	}
}

func (c canvas) circle(x, y, radius float64, paint color.NRGBA) {
	for py := int(math.Floor(y - radius - 1)); py < int(math.Ceil(y+radius+1)); py++ {
		for px := int(math.Floor(x - radius - 1)); px < int(math.Ceil(x+radius+1)); px++ {
			coverage := radius + .5 - math.Hypot(float64(px)+.5-x, float64(py)+.5-y)
			c.blend(px, py, paint, coverage)
		}
	}
}

// A compact built-in stroke alphabet keeps graph annotation self-contained.
// Each row describes five columns, from the most significant bit to the least.
var alphabet = map[rune][7]uint8{
	'0': {14, 17, 19, 21, 25, 17, 14}, '1': {4, 12, 4, 4, 4, 4, 14},
	'2': {14, 17, 1, 2, 4, 8, 31}, '3': {30, 1, 1, 14, 1, 1, 30},
	'4': {2, 6, 10, 18, 31, 2, 2}, '5': {31, 16, 16, 30, 1, 1, 30},
