func textWidth(text string, size float64) float64 {
	return float64(len([]rune(text))) * size * .6
}

func (c canvas) text(x, baseline, size float64, text string, paint color.NRGBA) {
	scale := size / 10
	for _, ch := range text {
		if ch == ' ' {
			x += size * .6
			continue
		}
		glyph, ok := alphabet[ch]
		if !ok {
			glyph = alphabet['?']
		}
		for y, row := range glyph {
			for xx := 0; xx < 5; xx++ {
				if row&(1<<uint(4-xx)) != 0 {
					c.box(x+float64(xx)*scale, baseline-float64(7-y)*scale,
						x+float64(xx+1)*scale, baseline-float64(6-y)*scale, paint)
				}
			}
		}
		x += size * .6
	}
}

func formatNumber(v float64) string {
	magnitude := math.Abs(v)
	suffix := ""
	for _, unit := range []struct {
		scale  float64
		suffix string
	}{{1e12, "T"}, {1e9, "G"}, {1e6, "M"}, {1e3, "k"}} {
		if magnitude >= unit.scale {
			v /= unit.scale
			suffix = unit.suffix
			break
		}
	}
	return strconv.FormatFloat(v, 'f', -1, 64) + suffix
}

func niceStep(value float64) float64 {
	if value <= 0 || math.IsNaN(value) || math.IsInf(value, 0) {
		return 1
	}
	power := math.Pow(10, math.Floor(math.Log10(value)))
	fraction := value / power
	if fraction <= 1 {
		return power
	}
	if fraction <= 2 {
		return 2 * power
	}
	if fraction <= 5 {
		return 5 * power
	}
	return 10 * power
}

func drawGraph(c canvas, g []series, rect image.Rectangle, interval time.Duration) {
	left := float64(rect.Min.X + 13)
	top := float64(rect.Min.Y + 12)
	right := float64(rect.Max.X - 51)
	bottom := float64(rect.Max.Y - 26)
	gray := color.NRGBA{180, 180, 180, 255}
	if rect.Dx() < 14 {
		return
	}
	minimum, maximum := 0.0, 0.0
	for _, s := range g {
		if s.marker {
			continue
		}
		for _, v := range s.values {
			if !math.IsNaN(v) && !math.IsInf(v, 0) {
				minimum, maximum = math.Min(minimum, v), math.Max(maximum, v)
			}
		}
	}
	if minimum == maximum {
		maximum = minimum + 1
	}
	span := maximum - minimum
	mapY := func(v float64) float64 { return bottom - (v-minimum)/span*(bottom-top) }
	if top < bottom {
		c.line(left, top, left, bottom, 1, gray)
		c.line(right, top, right, bottom, 1, gray)
	}
	if right > left {
		c.line(left, bottom, right, bottom, 1, gray)
	}
	for n, s := range g {
		paint := seriesColors[n%len(seriesColors)]
		values := s.values
		if len(values) == 0 {
			// Like other history-size errors this is a run-time, not a spec,
			// error, and therefore occurs only when a frame is rendered.
			_ = values[len(values)-1]
		}
		if len(values) < 2 || right <= left || bottom <= top {
			continue
		}
		stride := (right - left) / float64(len(values)-1)
		if s.marker {
			for i, v := range values {
				if v != 0 {
					x := left + float64(i)*stride
					c.line(x, top, x, bottom, 1, paint)
				}
			}
			continue
		}
		for i := 1; i < len(values); i++ {
			x0, x1 := left+float64(i-1)*stride, left+float64(i)*stride
			y0, y1 := mapY(values[i-1]), mapY(values[i])
			fill := paint
			fill.A = 20
			c.polygon([]vector{{x0, bottom}, {x0, y0}, {x1, y1}, {x1, bottom}}, fill)
			c.line(x0, y0, x1, y1, 2, paint)
		}
		lastY := mapY(values[len(values)-1])
		c.circle(right, lastY, 3, paint)
		c.text(right+4, lastY+5, 16, formatNumber(values[len(values)-1]), paint)
	}
	if right > left {
		step := niceStep(span / math.Max(1, (bottom-top)/40))
		for v := math.Ceil(minimum/step) * step; v <= maximum+step*.001; v += step {
			y := mapY(v)
			c.line(right, y, right+4, y, 1, gray)
			c.text(right+8, y+5, 14, formatNumber(math.Round(v/step)*step), gray)
			if step == 0 {
				break
			}
		}
		count := 0
		if len(g) > 0 {
			count = len(g[0].values)
		}
		if count > 1 {
			tick := maxInt(1, int(math.Ceil(float64(count-1)/math.Max(1, (right-left)/54))))
			for i := 0; i < count; i += tick {
				x := left + float64(i)*(right-left)/float64(count-1)
				c.line(x, bottom, x, bottom+4, 1, gray)
				seconds := float64(i-count+1) * interval.Seconds()
				label := fmt.Sprintf("%.0fs", seconds)
				c.text(x-textWidth(label, 14)/2, bottom+21, 14, label, gray)
			}
		}
	}
	legendX, legendY := left+6, top+17
	for i, s := range g {
		label := strings.ReplaceAll(s.path, "\n", " ")
		w := textWidth(label, 14) + 29
		if legendX+w > right && legendX > left+6 {
			legendX, legendY = left+6, legendY+20
		}
		c.box(legendX-5, legendY-17, legendX+w, legendY+7, color.NRGBA{0, 0, 0, 100})
		c.text(legendX, legendY, 14, label, gray)
		c.line(legendX+w-23, legendY-5, legendX+w-5, legendY-5, 2, seriesColors[i%len(seriesColors)])
		legendX += w + 4
	}
}

func rasterize(width, height int, graphs [][]series, interval time.Duration) *image.RGBA {
	img := image.NewRGBA(image.Rectangle{Max: image.Point{X: width, Y: height}})
	if len(graphs) == 0 {
		return img
	}
	partHeight := height / len(graphs)
	for i, graph := range graphs {
		rect := image.Rect(0, i*partHeight, width, (i+1)*partHeight)
		part := img.SubImage(rect).(*image.RGBA)
		drawGraph(canvas{part}, graph, rect, interval)
	}
	return img
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}
