package main

import (
	"encoding/base64"
	"fmt"
	"image"
	"image/png"
	"io"
	"os"
	"sort"
	"strings"
)

func (t *terminal) render(points *pointStore, rows int) {
	width, height, err := t.dimensions(rows)
	if err != nil {
		fail("Cannot get window size: ", err)
	}
	if width == 0 || height == 0 {
		fail(fmt.Sprintf("cannot render graph: png: invalid format: invalid image size: %dx%d", width, height))
	}

	switch t.mode {
	case itermGraphics:
		fmt.Fprintf(os.Stdout, "\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:", width, height)
		defer fmt.Fprint(os.Stdout, "\x07")
		img := rasterize(width, height, points.snapshot(), points.interval)
		writer := base64.NewEncoder(base64.StdEncoding, os.Stdout)
		if err := png.Encode(writer, img); err != nil {
			fail("cannot render graph:", err)
		}
		// The OSC image stream ends with BEL, without padding the final
		// incomplete group of the base64 stream.
	case kittyGraphics:
		t.imageID++
		fmt.Fprintf(os.Stdout, "\x1b_Ga=T,f=100,t=d,i=%d,X=0,Y=0,q=2;", t.imageID)
		defer fmt.Fprint(os.Stdout, "\x1b\\")
		img := rasterize(width, height, points.snapshot(), points.interval)
		writer := base64.NewEncoder(base64.StdEncoding, os.Stdout)
		if err := png.Encode(writer, img); err != nil {
			fail("cannot render graph:", err)
		}
		writer.Close()
	case sixelGraphics:
		img := rasterize(width, height, points.snapshot(), points.interval)
		if err := writeSixel(os.Stdout, img); err != nil {
			fail("cannot render graph:", err)
		}
	}
}

type rgb struct{ r, g, b uint8 }

// Sixel emission uses a palette followed by six-row bit planes. Transparent
// pixels are left untouched, and runs are compacted with the sixel repeat
// operator. Palette components use the protocol's 0..100 percentage range.
func writeSixel(w io.Writer, image *image.RGBA) error {
	bounds := image.Bounds()
	paletteSet := make(map[rgb]bool)
	for y := bounds.Min.Y; y < bounds.Max.Y; y++ {
		for x := bounds.Min.X; x < bounds.Max.X; x++ {
			p := image.RGBAAt(x, y)
			if p.A == 0 {
				continue
			}
			paletteSet[rgb{p.R, p.G, p.B}] = true
		}
	}
	palette := make([]rgb, 0, len(paletteSet))
	for c := range paletteSet {
		palette = append(palette, c)
	}
	sort.Slice(palette, func(i, j int) bool {
		a, b := palette[i], palette[j]
		if int(a.r)+int(a.g)+int(a.b) != int(b.r)+int(b.g)+int(b.b) {
			return int(a.r)+int(a.g)+int(a.b) < int(b.r)+int(b.g)+int(b.b)
		}
		if a.r != b.r {
			return a.r < b.r
		}
		if a.g != b.g {
			return a.g < b.g
		}
		return a.b < b.b
	})
	var stream strings.Builder
	stream.WriteString("\x1bP0;0;8q\"1;1")
	for i, c := range palette {
		fmt.Fprintf(&stream, "#%d;2;%d;%d;%d", i+1, int(c.r)*100/255, int(c.g)*100/255, int(c.b)*100/255)
	}
	for y := bounds.Min.Y; y < bounds.Max.Y; y += 6 {
		first := true
		for index, color := range palette {
			row := make([]byte, bounds.Dx())
			last := -1
			for x := bounds.Min.X; x < bounds.Max.X; x++ {
				var mask byte
				for b := 0; b < 6 && y+b < bounds.Max.Y; b++ {
					pixel := image.RGBAAt(x, y+b)
					if pixel.A != 0 && (rgb{pixel.R, pixel.G, pixel.B}) == color {
						mask |= 1 << uint(b)
					}
				}
				row[x-bounds.Min.X] = 63 + mask
				if mask != 0 {
					last = x - bounds.Min.X
				}
			}
			if last < 0 {
				continue
			}
			if !first {
				stream.WriteByte('$')
			}
			first = false
			fmt.Fprintf(&stream, "#%d", index+1)
			for x := 0; x <= last; {
				end := x + 1
				for end <= last && row[end] == row[x] {
					end++
				}
				if end-x >= 4 {
					fmt.Fprintf(&stream, "!%d%c", end-x, row[x])
				} else {
					for j := x; j < end; j++ {
						stream.WriteByte(row[x])
					}
				}
				x = end
			}
		}
		if y+6 <= bounds.Max.Y {
			stream.WriteByte('-')
		}
	}
	stream.WriteString("\x1b\\")
	_, err := io.WriteString(w, stream.String())
	return err
}
